{% doc %}
  Fulldev UI field styles. Use native markup with its data-slot parts.
{% enddoc %}

{{ 'ui-field.css' | asset_url | stylesheet_tag }}

[data-slot='label'],
[data-slot='field-label'] {
  display: flex;
  align-items: center;
  gap: calc(var(--spacing) * 2);
  font-size: 0.875rem;
  font-weight: 500;
  line-height: 1;
}
/* Fulldev UI's field set: a fieldset of fields or options under a legend. A legend sits outside its
   fieldset's flex layout, so it keeps the field gap as its margin. */
[data-slot='field-set'] {
  display: flex;
  flex-direction: column;
  gap: calc(var(--spacing) * 6);
  min-width: 0;
  margin: 0;
  padding: 0;
  border: 0;
}
[data-slot='field-legend'] {
  display: flex;
  align-items: center;
  gap: calc(var(--spacing) * 2);
  margin-bottom: calc(var(--spacing) * 3);
  padding: 0;
  font-size: 1rem;
  font-weight: 500;
  line-height: 1;
}
[data-slot='field-legend'][data-variant='label'] {
  font-size: 0.875rem;
}
[data-slot='field'] {
  display: flex;
  flex-direction: column;
  gap: calc(var(--spacing) * 3);
  width: 100%;
}
/* An input and its button side by side, as in newsletter and search forms. */
[data-slot='field'][data-orientation='horizontal'] {
  flex-direction: row;
  align-items: center;
}
[data-slot='field'][data-orientation='horizontal'] > :is(input, select, textarea) {
  flex: 1;
}
[data-slot='field-group'] {
  display: flex;
  flex-direction: column;
  gap: calc(var(--spacing) * 7);
}
/* Two fields side by side from 640px. */
.field-row {
  display: grid;
  gap: calc(var(--spacing) * 4);
}
@media (min-width: 640px) {
  .field-row {
    grid-template-columns: 1fr 1fr;
  }
}
[data-slot='field-description'] {
  font-size: 0.875rem;
  color: var(--muted-foreground);
}
[data-slot='field-error'] {
  font-size: 0.875rem;
  color: var(--destructive);
}
